package com.ahope.ds.web.superadmin.mngTerms.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.extension.annotation.RequestParamMap;
import com.ahope.ds.common.util.CommonUtil;
import com.ahope.ds.common.web.controller.CommonController;
import com.ahope.ds.web.superadmin.mngTerms.service.MngTermsService;

import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.Parameter;
import io.swagger.v3.oas.annotations.Parameters;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.servlet.http.HttpSession;

@Tag(name = "SuperAdmin - Management Terms", description = "슈퍼관리자 관리자 약관 API")
@Controller
@RequestMapping("/web/super/admin/mngTerms")
public class MngTermsController extends CommonController {

	@Autowired
	private MngTermsService mngTermsService;

	@Operation(summary = "관리자 약관 등록", description = "새로운 관리자 약관을 등록합니다.")
	@Parameters({
		@Parameter(name = "link", description = "약관 링크", example = "https://google.com", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "termsType", description = "약관 타입 (01:개인정보처리방침, 02:위치정보이용약관)", example = "02", required = true, schema = @Schema(type = "string"))
	})
	@RequestMapping(value = "", method = RequestMethod.POST)
	public String createNotice(@RequestParamMap(requiredValues= {"link"}) ParamMap param, Model model) throws LogicException {
		if (CommonUtil.isVulnerability(new String[] {"link"}, param)) {
			throw new LogicException("VULNERABLE_VALUE", "002");
		}
		model.addAllAttributes(mngTermsService.createMngTerms(param));
		return JSON_VIEW;
	}

	@Operation(summary = "관리자 약관 상세 조회", description = "관리자 약관 상세 정보를 조회합니다.")
	@Parameters({
		@Parameter(name = "termsType", description = "약관 타입 (01:개인정보처리방침, 02:위치정보이용약관)", example = "02", required = true, schema = @Schema(type = "string"))
	})
	@RequestMapping(value = "", method = RequestMethod.GET) 
	public String getNotice(@RequestParamMap ParamMap param, Model model) {
		model.addAllAttributes(mngTermsService.getMngTerms(param));
		return JSON_VIEW;
	}


	@Operation(summary = "개인정보 활용동의 상세 조회", description = "개인정보 활용동의 상세 정보를 조회합니다.")
	@RequestMapping(value = "/agree/{mngTermsSeq}", method = RequestMethod.GET)
	public String detailWebTermsView(
			@Parameter(description = "관리자 약관 시퀀스", example = "1")
			@PathVariable("mngTermsSeq") Long mngTermsSeq,
			Model model) {
		model.addAllAttributes(mngTermsService.getMngAgreeTermsDetail(mngTermsSeq));
		return JSON_VIEW;
	}

	@Operation(summary = "개인정보 활용동의 목록 조회", description = "개인정보 활용동의 목록을 조회합니다.")
	@Parameters({
		@Parameter(name = "start", description = "페이징 시작 위치", example = "0", required = true, schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "length", description = "페이지당 표시할 데이터 개수", example = "10", required = true, schema = @Schema(type = "integer", format = "int32"))
	})
	@RequestMapping(value = "/agree/ajax", method = RequestMethod.GET)
	public String getWebTermsList(@RequestParamMap ParamMap param,  Model model) {
		model.addAllAttributes(mngTermsService.getMngAgreeTermsList(param));
		return JSON_VIEW;
	}

	@Operation(summary = "개인정보 활용동의 등록", description = "새로운 개인정보 활용동의를 등록합니다.")
	@Parameters({
		@Parameter(name = "title", description = "약관 명", example = "약관", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "version", description = "약관 버전", example = "1", required = true, schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "content", description = "약관 내용", example = "[필수] 개인정보 수집 및 이용 동의", required = true, schema = @Schema(type = "string"))
	})
	@RequestMapping(value = "/agree", method = RequestMethod.POST) 
	public String createWebTerms(@RequestParamMap(requiredValues= {"title", "version", "content"}) ParamMap param, Model model, HttpSession session) throws LogicException {
		model.addAllAttributes(mngTermsService.createMngAgreeTerms(param));
		return JSON_VIEW;
	}
}

