package com.ahope.ds.web.superadmin.mngTerms.service;

import java.util.List;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.stereotype.Service;
import org.springframework.transaction.TransactionStatus;
import org.springframework.transaction.support.DefaultTransactionDefinition;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.bean.ResultMap;
import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.web.service.CommonService;
import com.ahope.ds.web.superadmin.mngTerms.dao.MngTermsDAO;

@Service
public class MngTermsService extends CommonService {

	@Autowired
	private MngTermsDAO mngTermsDAO;
	
	@Autowired
	private DataSourceTransactionManager transactionManager;
	
	//관리자 약관 상세
	public ResultMap getMngTerms(ParamMap param) {
		ResultMap result = mngTermsDAO.getMngTerms(param);
		return result;
	}
	
	//관리자 약관 등록
	public ResultMap createMngTerms(ParamMap param) {
		ResultMap result = new ResultMap();
		TransactionStatus transactionStatus = transactionManager.getTransaction(new DefaultTransactionDefinition());
		try {
			long mngTermsSeq = mngTermsDAO.getNextMngTermsSeq();
			param.put("regAccountId", param.getSessionAttribute("loginId"));
			param.put("regAccountSeq", param.getSessionAttribute("loginAccountSeq"));
			param.put("mngTermsSeq", mngTermsSeq);
			param.put("link", param.getString("link"));
			mngTermsDAO.createMngTerms(param);
						
			result.setErr("000");
			transactionManager.commit(transactionStatus);
		} catch (Exception e) {
			e.printStackTrace();
			transactionManager.rollback(transactionStatus);
			result.setErr("001");
			logger.error(e.getMessage());
		}
		return result;
	}
	
	//약관 목록 조회
	public ResultMap getMngAgreeTermsList(ParamMap param) {
		ResultMap result = new ResultMap();
		
		try {
			List<ParamMap> mngTermsList = mngTermsDAO.getMngAgreeTermsList(param);
			Integer mngTermsListCount = mngTermsDAO.getMngAgreeTermsListCount(param);
		
			result.put("iTotalRecords", mngTermsListCount);
			result.put("iTotalDisplayRecords", mngTermsListCount);		
			result.put("aaData", mngTermsList);
		} catch (Exception e) {
			result.setErr("999");
			result.setErrMsg("Unknown error");
			logger.error(e.getMessage());
		}
		
		return result;
	}
	
	//약관 상세
	public ResultMap getMngAgreeTermsDetail(Long mngAgreeTermsSeq) {
		ResultMap result = new ResultMap();
	
		try {
			result.put("mngTerms", mngTermsDAO.getMngAgreeTermsDetail(mngAgreeTermsSeq));
		} catch (Exception e) {
			result.setErr("999");
			result.setErrMsg("Unknown error");
			logger.error(e.getMessage());
		}
		
		return result;
	}
	
	//약관 등록
	public ResultMap createMngAgreeTerms(ParamMap param) throws LogicException {
		ResultMap result = new ResultMap();
		Boolean isRecent = mngTermsDAO.checkMngAgreeTermsIsRecent(param.getInt("version"));
		
		if (!isRecent) {
			throw new LogicException("Version must be current or higher", "001");
		}
		
		TransactionStatus transactionStatus = transactionManager.getTransaction(new DefaultTransactionDefinition());

		try {
			param.put("regAccountId", param.getSessionAttribute("loginId"));
			param.put("regAccountSeq", param.getSessionAttribute("loginAccountSeq"));
			param.put("mngAgreeTermsSeq", mngTermsDAO.getNextMngAgreeTermsSeq());
			mngTermsDAO.createMngAgreeTerms(param);
			transactionManager.commit(transactionStatus);
		} catch (Exception e) {
			e.printStackTrace();
			transactionManager.rollback(transactionStatus);
			result.setErr("999");
			result.setErrMsg("Unknown error");
		}
		return result;
	}
}
=== DAO ===
package com.ahope.ds.web.superadmin.mngTerms.dao;

import java.util.List;

import org.springframework.stereotype.Repository;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.bean.ResultMap;
import com.ahope.ds.common.web.dao.CommonDAO;

@Repository
public class MngTermsDAO extends CommonDAO {
	public long getNextMngTermsSeq() throws Exception {
		return defaultSelectOne("mngTerms.getNextMngTermsSeq");
	}
	
	public int createMngTerms(ParamMap param) {
		return defaultInsert("mngTerms.createMngTerms", param);
	}
	
	public ResultMap getMngTerms(ParamMap param) {
		return defaultSelectOne("mngTerms.getMngTerms", param);
	}
	
	
	
	//약관 목록 수 조회
	public Integer getMngAgreeTermsListCount(ParamMap param) {
		return selectOne("mngTerms.getMngAgreeTermsListCount", param);
	}

	//약관 목록 조회
	public List<ParamMap> getMngAgreeTermsList(ParamMap param) {
		return selectList("mngTerms.getMngAgreeTermsList", param);
	}
	
	//약관 상세 정보 조회
	public ResultMap getMngAgreeTermsDetail(Long mngAgreeTermsSeq) {
		return selectOne("mngTerms.getMngAgreeTermsDetail", mngAgreeTermsSeq);
	}
	
	//약관 등록 시 버전 검증
	public Boolean checkMngAgreeTermsIsRecent(Integer version) {
		return selectOne("mngTerms.checkMngAgreeTermsIsRecent", version);
	}
	
	public long getNextMngAgreeTermsSeq() throws Exception {
		return defaultSelectOne("mngTerms.getNextMngAgreeTermsSeq");
	}
	
	//약관 등록
	public Integer createMngAgreeTerms(ParamMap param) {
		return insert("mngTerms.createMngAgreeTerms",  param);
	}
	
}
=== mapper xml ===
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE mapper PUBLIC "-//ibatis.apache.org//DTD Mapper 3.0//EN" "http://ibatis.apache.org/dtd/ibatis-3-mapper.dtd">
<mapper namespace="mngTerms">
	
	<select id="getNextMngTermsSeq" resultType="long">
		SELECT	FUN_NEXT_SEQ_VAL('MNG_TERMS')
	</select>
	
	<insert id="createMngTerms" parameterType="param">
		INSERT	INTO MNG_TERMS
			(
				MNG_TERMS_SEQ
				, LINK
				, TERMS_TYPE
				, REG_ACCOUNT_SEQ
				, REG_ACCOUNT_ID
				, REG_TIME
			)
		VALUES
			(
			 	#{mngTermsSeq}
			 	, #{link}
			 	, #{termsType}
			 	, #{regAccountSeq}
			 	, #{regAccountId}
			 	, now()
			)
	</insert>
	
	<select id="getMngTerms" parameterType="param" resultType="result">
        SELECT  MNG_TERMS_SEQ AS "mngTermsSeq"
                , LINK AS "link"
        FROM    MNG_TERMS
        WHERE   TERMS_TYPE = #{termsType}
        ORDER   BY REG_TIME DESC
        LIMIT   1
    </select>

    <!-- 약관 목록 조회 -->
    <select id="getMngAgreeTermsList" parameterType="param" resultType="result">
        SELECT      MNG_AGREE_TERMS_SEQ AS 'mngAgreeTermsSeq'
		            , TITLE AS 'title'
		            , VERSION AS 'version'
		            , REG_ACCOUNT_ID AS 'regAccountName'
		            , DATE_FORMAT(REG_TIME, '%Y.%m.%d') AS 'regTime'
		FROM        MNG_AGREE_TERMS
		ORDER BY    VERSION DESC, REG_TIME DESC
        LIMIT       #{length} OFFSET #{start}
    </select>
    
    <!-- 약관 목록 수 조회 -->
    <select id="getMngAgreeTermsListCount" resultType="integer">
        SELECT  COUNT(1)
        FROM    MNG_AGREE_TERMS
    </select>
    
    <!-- 약관 상세 정보 조회 -->
    <select id="getMngAgreeTermsDetail" parameterType="param" resultType="result">
        SELECT      MNG_AGREE_TERMS_SEQ AS 'mngAgreeTermsSeq'
                    , TITLE AS 'title'
                    , CONTENT AS 'content'
                    , VERSION AS 'version'
        FROM        MNG_AGREE_TERMS
        WHERE       MNG_AGREE_TERMS_SEQ = #{mngAgreeTermsSeq}
    </select>
    
    <!-- 약관 등록 시 버전 검증 -->
    <select id="checkMngAgreeTermsIsRecent" resultType="Boolean">
        SELECT      IF(IFNULL(MAX(VERSION), 0) <![CDATA[ <= ]]> #{version}, true, false) AS 'isRecent'
		FROM        MNG_AGREE_TERMS
    </select>
    
    <!-- 약관 등록 -->
    <insert id="createMngAgreeTerms" parameterType="param">
        INSERT INTO MNG_AGREE_TERMS
        (
        MNG_AGREE_TERMS_SEQ
        , TITLE
        , CONTENT
        , VERSION
        , REG_ACCOUNT_SEQ
        , REG_ACCOUNT_ID
        , REG_TIME
        )
        VALUES
        (
        #{mngAgreeTermsSeq}
        , #{title}
        , #{content}
        , #{version}
        , #{regAccountSeq}
        , #{regAccountId}
        , NOW()
        )
    </insert>
    
    <select id="getNextMngAgreeTermsSeq" resultType="long">
        SELECT  FUN_NEXT_SEQ_VAL('MNG_AGREE_TERMS')
    </select>

</mapper>

