package com.ahope.ds.common.config;

import java.util.List;

import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.method.support.HandlerMethodArgumentResolver;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.PathMatchConfigurer;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
import org.springframework.web.servlet.i18n.LocaleChangeInterceptor;
import org.springframework.web.servlet.view.BeanNameViewResolver;
import org.springframework.web.servlet.view.json.MappingJackson2JsonView;

import com.ahope.ds.common.extension.resolver.RequestJsonArgumentResolver;
import com.ahope.ds.common.extension.resolver.RequestParamMapArgumentResolver;
import com.ahope.ds.common.interceptor.AdminLoginInterceptor;
import com.ahope.ds.common.interceptor.APILoginInterceptor;
import com.ahope.ds.common.interceptor.ClientLoginInterceptor;
import com.ahope.ds.common.interceptor.SuperAdminLoginInterceptor;
import com.ahope.ds.common.interceptor.AccessInterceptor;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

/**
 * MVC 설정 — 인터셉터, ArgumentResolver, ViewResolver.
 */
@Configuration
@SuppressWarnings("deprecation")
public class WebMvcConfig implements WebMvcConfigurer {

    private final SuperAdminLoginInterceptor superAdminInterceptor;
    private final AdminLoginInterceptor adminInterceptor;
    private final APILoginInterceptor apiInterceptor;
    private final ClientLoginInterceptor clientInterceptor;
    private final AccessInterceptor AccessInterceptor;

    public WebMvcConfig(SuperAdminLoginInterceptor superAdminInterceptor,
                        AdminLoginInterceptor adminInterceptor,
                        APILoginInterceptor apiInterceptor,
                        ClientLoginInterceptor clientInterceptor,
                        AccessInterceptor AccessInterceptor) {
        this.superAdminInterceptor = superAdminInterceptor;
        this.adminInterceptor = adminInterceptor;
        this.apiInterceptor = apiInterceptor;
        this.clientInterceptor = clientInterceptor;
        this.AccessInterceptor = AccessInterceptor;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        LocaleChangeInterceptor localeInterceptor = new LocaleChangeInterceptor();
        localeInterceptor.setParamName("lang");
        registry.addInterceptor(localeInterceptor);

        registry.addInterceptor(AccessInterceptor)
                .addPathPatterns("/web/admin/plte-api", "/v3/api-docs",
                        "/web/admin/karate-report", "/web/admin/karate-report/data");

        registry.addInterceptor(superAdminInterceptor)
                .addPathPatterns("/web/super/admin/**", "/web/phoneList")
                .excludePathPatterns("/webjars/**");

        registry.addInterceptor(adminInterceptor)
                .addPathPatterns("/web/admin/**")
                .excludePathPatterns("/webjars/**", "/web/admin/plte-api",
                        "/web/admin/karate-report", "/web/admin/karate-report/data");

        registry.addInterceptor(apiInterceptor)
                .addPathPatterns("/api/clients/**")
                .excludePathPatterns("/api/clients/error/*", "/api/clients/test/*");

        registry.addInterceptor(clientInterceptor)
                .addPathPatterns("/client/**");
    }

    @Override
    public void addArgumentResolvers(List<HandlerMethodArgumentResolver> resolvers) {
        resolvers.add(new RequestParamMapArgumentResolver());
        resolvers.add(new RequestJsonArgumentResolver());
    }

    @Override
    public void configurePathMatch(PathMatchConfigurer configurer) {
        // trailing-slash 호환 유지 (Spring 6 deprecated, 기존 URL 패턴 보호)
        configurer.setUseTrailingSlashMatch(true);
    }

    @Bean
    public BeanNameViewResolver beanNameViewResolver() {
        BeanNameViewResolver resolver = new BeanNameViewResolver();
        resolver.setOrder(0);
        return resolver;
    }

    @Bean
    public ObjectMapper jsonViewObjectMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());
        return mapper;
    }

    @Bean("jsonView")
    public MappingJackson2JsonView jsonView(
            @Qualifier("jsonViewObjectMapper") ObjectMapper objectMapper) {
        MappingJackson2JsonView view = new MappingJackson2JsonView();
        view.setContentType("application/json;charset=UTF-8");
        view.setObjectMapper(objectMapper);
        return view;
    }
}
