=== TestUtil ===
package com.ahope.ds.blackbox;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.Statement;

/**
 * JDK 8 호환 테스트 유틸리티
 */
class TestUtil {

    static {
        // POST/PUT 302 redirect는 RestAssured 기본 설정으로 follow되지 않음
        // 각 테스트에서 .redirects().follow(true)를 명시하거나, 302를 기대하도록 설계
    }

    static byte[] readAllBytes(InputStream is) throws Exception {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] data = new byte[4096];
        int bytesRead;
        while ((bytesRead = is.read(data, 0, data.length)) != -1) {
            buffer.write(data, 0, bytesRead);
        }
        return buffer.toByteArray();
    }

    static void executeSql(Connection conn, String resourcePath, Class<?> clazz) {
        try (InputStream is = clazz.getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(readAllBytes(is), StandardCharsets.UTF_8);
            StringBuilder cleaned = new StringBuilder();
            for (String rawLine : sql.split("\n")) {
                String line = rawLine.trim();
                if (line.startsWith("--") || line.isEmpty()) continue;
                cleaned.append(line).append(" ");
            }
            for (String statement : cleaned.toString().split(";")) {
                String trimmed = statement.trim();
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL execution failed: " + resourcePath, e);
        }
    }

    static String readResource(String resourcePath, Class<?> clazz) {
        try (InputStream is = clazz.getClassLoader().getResourceAsStream(resourcePath)) {
            return new String(readAllBytes(is), StandardCharsets.UTF_8);
        } catch (Exception e) {
            throw new RuntimeException("Resource read failed: " + resourcePath, e);
        }
    }

    /**
     * 관리자 로그인 세션을 획득하여 SESSION 쿠키를 반환한다.
     * 1단계: POST /web/login/ajax (id, pw) → accountSeq 반환
     * 2단계: JDBC로 ACCOUNT_SMS에서 인증번호 조회
     * 3단계: POST /web/login/sms (accountSeq, certificationNo) → 세션 생성
     * 3-B단계: 약관 동의가 필요하면 POST /web/login/agreeTerms 호출
     * 4단계: tokenErr="001"이면 POST /web/login/token 호출하여 loginToken 발급
     *
     * @param baseUrl 서버 URL (예: http://localhost:8080)
     * @param id 관리자 ID
     * @param pw 관리자 비밀번호
     * @param conn DB 연결
     * @return SESSION 쿠키 값
     */
    static String adminLogin(String baseUrl, String id, String pw, Connection conn) {
        // 1단계: 로그인 시도 → SMS 인증번호 발송 + accountSeq 반환
        io.restassured.response.Response loginResp = io.restassured.RestAssured.given()
            .baseUri(baseUrl)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("id", id)
            .formParam("pw", pw)
        .when()
            .post("/web/login/ajax");

        String err = loginResp.jsonPath().getString("err");
        if (!"000".equals(err)) {
            throw new RuntimeException("Login step 1 failed: err=" + err);
        }
        long accountSeq = loginResp.jsonPath().getLong("accountSeq");

        // SESSION는 1단계에서 발급됨 — 이후 모든 요청에 이 쿠키 사용
        String jsessionId = loginResp.getCookie("SESSION");
        if (jsessionId == null || jsessionId.isEmpty()) {
            throw new RuntimeException("No SESSION cookie from login/ajax");
        }

        // 2단계: DB에서 인증번호 직접 조회
        String certNo;
        try (java.sql.PreparedStatement ps = conn.prepareStatement(
                "SELECT CERTIFICATION_NO FROM ACCOUNT_SMS WHERE ACCOUNT_SEQ = ?")) {
            ps.setLong(1, accountSeq);
            java.sql.ResultSet rs = ps.executeQuery();
            if (!rs.next()) throw new RuntimeException("No SMS info found for accountSeq=" + accountSeq);
            certNo = rs.getString(1);
        } catch (Exception e) {
            throw new RuntimeException("Failed to read SMS certification", e);
        }

        // 3단계: SMS 인증 → 세션 생성
        io.restassured.response.Response smsResp = io.restassured.RestAssured.given()
            .baseUri(baseUrl)
            .cookie("SESSION", jsessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("id", id)
            .formParam("pw", pw)
            .formParam("accountSeq", accountSeq)
            .formParam("certificationNo", certNo)
        .when()
            .post("/web/login/sms");

        String smsErr = smsResp.jsonPath().getString("err");
        if (!"000".equals(smsErr)) {
            throw new RuntimeException("Login step 2 (SMS) failed: err=" + smsErr);
        }

        // 3-B단계: 약관 동의가 필요한 경우 (AUTHZ가 01, 07이 아닌 계정)
        String termsJson = smsResp.jsonPath().getString("terms");
        if (termsJson != null) {
            long mngAgreeTermsSeq = smsResp.jsonPath().getLong("terms.latestTerms.mngAgreeTermsSeq");
            int version = smsResp.jsonPath().getInt("terms.latestTerms.version");

            io.restassured.response.Response agreeResp = io.restassured.RestAssured.given()
                .baseUri(baseUrl)
                .cookie("SESSION", jsessionId)
                .header("X-Requested-With", "XMLHttpRequest")
                .contentType("application/x-www-form-urlencoded")
                .formParam("id", id)
                .formParam("pw", pw)
                .formParam("accountSeq", accountSeq)
                .formParam("mngAgreeTermsSeq", mngAgreeTermsSeq)
                .formParam("version", version)
            .when()
                .post("/web/login/agreeTerms");

            String agreeErr = agreeResp.jsonPath().getString("err");
            if (agreeErr != null && !"000".equals(agreeErr)) {
                String agreeErrMsg = agreeResp.jsonPath().getString("errMsg");
                // errMsg가 숫자 코드(100, 200 등)이면 정상 로그인 완료
                if (agreeErrMsg == null || (!agreeErrMsg.matches("\\d+") && !"success".equalsIgnoreCase(agreeErrMsg))) {
                    throw new RuntimeException("Login step 3-B (agreeTerms) failed: err=" + agreeErr + ", errMsg=" + agreeErrMsg);
                }
            }

            // agreeTerms 응답에서 tokenErr 확인
            String tokenErr = agreeResp.jsonPath().getString("tokenErr");
            if ("001".equals(tokenErr)) {
                // 이미 로그인된 세션이 있어 loginToken이 설정되지 않음 → token 발급 요청
                io.restassured.RestAssured.given()
                    .baseUri(baseUrl)
                    .cookie("SESSION", jsessionId)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .contentType("application/x-www-form-urlencoded")
                .when()
                    .post("/web/login/token");
            }
        } else {
            // 약관 동의 불필요 — tokenErr 확인
            String tokenErr = smsResp.jsonPath().getString("tokenErr");
            if ("001".equals(tokenErr)) {
                io.restassured.RestAssured.given()
                    .baseUri(baseUrl)
                    .cookie("SESSION", jsessionId)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .contentType("application/x-www-form-urlencoded")
                .when()
                    .post("/web/login/token");
            }
        }

        return jsessionId;
    }

    /**
     * 서버의 가입자 등록 API를 통해 가입자를 등록하고, DB에서 암호화된 CTN을 반환한다.
     * SecurityModule 의존 테스트의 setup 데이터 준비에 사용.
     *
     * @param baseUrl 서버 URL
     * @param sessionId JOIN 관리자(AUTHZ=05) 세션 ID
     * @param ctn 평문 전화번호 (예: "01012345678")
     * @param corporationYn "1"(법인) 또는 "0"(개인)
     * @param managerName 관리자명
     * @param conn DB 연결
     * @return 서버가 암호화한 CTN 값
     */
    static String createMemberAndGetEncryptedCtn(String baseUrl, String sessionId, String ctn,
            String corporationYn, String managerName, Connection conn) {
        io.restassured.RestAssured.given()
            .baseUri(baseUrl)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("multipart/form-data")
            .multiPart("ctn", ctn)
            .multiPart("exceptionPolicy", "0")
            .multiPart("managerName", managerName)
            .multiPart("corporationYn", corporationYn)
            .multiPart("immediately", "false")
            .multiPart("noteLen", "0")
        .when().post("/web/admin/members/");

        try (java.sql.PreparedStatement ps = conn.prepareStatement(
                "SELECT CTN FROM MEMBER ORDER BY MEMBER_SEQ DESC LIMIT 1")) {
            java.sql.ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                return rs.getString("CTN");
            }
            throw new RuntimeException("Member not found after creation: ctn=" + ctn);
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("Failed to read encrypted CTN", e);
        }
    }

