                .keyId(keyAlias).build()
        ).keyMetadata().arn();

        com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKeyProvider provider =
            com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKeyProvider.builder()
                .defaultRegion(software.amazon.awssdk.regions.Region.of(region))
                .customRegionalClientSupplier(r -> kmsClient)
                .buildStrict(keyArn);

        com.amazonaws.encryptionsdk.caching.CryptoMaterialsCache cache =
            new com.amazonaws.encryptionsdk.caching.LocalCryptoMaterialsCache(100);
        cachingCmm = com.amazonaws.encryptionsdk.caching.CachingCryptoMaterialsManager.newBuilder()
