package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.containsString;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.nullValue;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test
 *
 * @target-controller MngTermsController
 *   (src/main/java/com/ahope/ds/web/superadmin/mngTerms/controller/MngTermsController.java)
 * @target-api GET /web/super/admin/mngTerms  (handler: getNotice)
 *
 * <p>파이프라인 산출물 근거:
 * <ul>
 *   <li>Step 2 test-plan: .nimbus/artifacts/test-plan/MngTermsService_getMngTerms.md
 *       — RED 파라미터 {@code termsType}(DB_WHERE), 체크리스트: NTC happy / ATC noData / ATC 요청거부</li>
 *   <li>Step 3-B analyze-auth-flow: /web/super/admin/** → SuperAdminLoginInterceptor.
 *       세션 {@code loginAuthz == Authz.SYSTEM("07")} 필요(SUPER/CONSULTING/GROUP은 mngTerms 화이트리스트 밖 → 403).
 *       계정 {@code accadmin}(AUTHZ=07) + {@link TestUtil#adminLogin} 로그인 체인으로 세션 확보.</li>
 *   <li>Step 3-C detect-external-calls: 외부 연동 없음(must_mock=[]). → WireMock 스텁 미해당.</li>
 *   <li>Step 3-D: 대상 테이블 MNG_TERMS 단일. DDL: TERMS_TYPE varchar(2), LINK varchar(200), MNG_TERMS_SEQ bigint PK.</li>
 * </ul>
 *
 * <p>대상 SQL(mngTerms.getMngTerms):
 * <pre>SELECT MNG_TERMS_SEQ AS "mngTermsSeq", LINK AS "link"
 * FROM MNG_TERMS WHERE TERMS_TYPE = #{termsType} ORDER BY REG_TIME DESC LIMIT 1</pre>
 * 서비스는 DAO 결과(ResultMap)를 그대로 반환한다. 매칭 행이 있으면 ResultMap 기본값 err="000" +
 * {mngTermsSeq, link}. 매칭 행이 없으면 DAO가 null → model.addAllAttributes(null)(널 세이프) → 빈 JSON {}.
 *
 * <p>병렬 안전: 각 NTC 메서드는 서로 다른 고유 TERMS_TYPE 코드(Z1/Z2/Z3, 타 테스트 미사용)와 고유 PK를
 * 사용하고, try/finally로 자기 데이터만 정리한다. 인증 계정 데이터(admin-account-list)만 @BeforeAll에서
 * 준비하며(공유 읽기전용 인증 인프라), 업무 데이터는 @BeforeAll에서 INSERT하지 않는다.
 * VTC/ATC 케이스는 매칭 행이 없어야 정상이므로 setup 데이터가 필요 없다.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class SuperAdminMngTermsBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final String DB_URL =
        System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant");
    private static final String DB_USER = System.getProperty("test.db.user", "smartplant");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "smartplant1234");

    private static final String API_PATH = "/web/super/admin/mngTerms";
    private static final String SETUP_SQL = "sql/super-admin-mng-terms-setup.sql";
    private static final String TEARDOWN_SQL = "sql/super-admin-mng-terms-teardown.sql";

    /** SuperAdmin(SYSTEM/07) 세션 쿠키 — 로그인 체인은 읽기전용이므로 병렬 공유 안전. */
    private static String sessionId;

    // 병렬 안전: 각 DB 작업마다 독립 Connection을 사용한다.
    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    @BeforeAll
    static void setUp() throws Exception {
        // 인증 계정 데이터 준비 후 SYSTEM(07) 관리자 로그인 (SuperAdminPagesBlackBoxTest와 동일 패턴)
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/admin-account-list-teardown.sql", SuperAdminMngTermsBlackBoxTest.class);
            TestUtil.executeSql(conn, "sql/admin-account-list-setup.sql", SuperAdminMngTermsBlackBoxTest.class);
            sessionId = TestUtil.adminLogin(BASE_URL, "accadmin", "testpw", conn);
        }
    }

    @AfterAll
    static void cleanup() throws Exception {
        try (Connection conn = getDbConnection()) {
            TestUtil.executeSql(conn, "sql/admin-account-list-teardown.sql", SuperAdminMngTermsBlackBoxTest.class);
        }
    }

    // =====================================================================
    // NTC — Happy Path (SuperAdmin 세션 + termsType 매칭 → 최신 1건)
    // 체크리스트: NTC_branch_getMngTerms_2 (test-plan)
    // 각 NTC는 REG_TIME이 다른 2건을 넣고 ORDER BY REG_TIME DESC LIMIT 1 → NEW 행을 기대한다.
    // =====================================================================

    /** [NTC_getNotice_privacyType] termsType='Z1' → 최신 행(970002) 1건 조회. */
    @Test
    void NTC_getNotice_privacyType() {
        String termsType = "Z1";
        Map<String, String> p = Map.of(
            "TERMS_TYPE", termsType,
            "SEQ_OLD", "970001", "LINK_OLD", "https://example.com/terms/privacy-old",
            "SEQ_NEW", "970002", "LINK_NEW", "https://example.com/terms/privacy");
        executeSqlTemplate(TEARDOWN_SQL, p);
        executeSqlTemplate(SETUP_SQL, p);
        try {
            given().log().ifValidationFails().baseUri(BASE_URL)
                .cookie("SESSION", sessionId)
                .header("X-Requested-With", "XMLHttpRequest")
                .queryParam("termsType", termsType)
            .when()
                .get(API_PATH)
            .then().log().ifValidationFails()
                .statusCode(200)
                .body("err", equalTo("000"))
                .body("mngTermsSeq", equalTo(970002))
                .body("link", equalTo("https://example.com/terms/privacy"));
        } finally {
            executeSqlTemplate(TEARDOWN_SQL, p);
        }
    }

    /** [NTC_getNotice_locationType] termsType='Z2' → 최신 행(970012) 1건 조회. */
    @Test
    void NTC_getNotice_locationType() {
        String termsType = "Z2";
        Map<String, String> p = Map.of(
            "TERMS_TYPE", termsType,
            "SEQ_OLD", "970011", "LINK_OLD", "https://example.com/terms/location-old",
            "SEQ_NEW", "970012", "LINK_NEW", "https://example.com/terms/location");
        executeSqlTemplate(TEARDOWN_SQL, p);
        executeSqlTemplate(SETUP_SQL, p);
        try {
            given().log().ifValidationFails().baseUri(BASE_URL)
                .cookie("SESSION", sessionId)
                .header("X-Requested-With", "XMLHttpRequest")
                .queryParam("termsType", termsType)
            .when()
                .get(API_PATH)
            .then().log().ifValidationFails()
                .statusCode(200)
                .body("err", equalTo("000"))
                .body("mngTermsSeq", equalTo(970012))
                .body("link", equalTo("https://example.com/terms/location"));
        } finally {
            executeSqlTemplate(TEARDOWN_SQL, p);
        }
    }

    /**
     * [NTC_getNotice_latestAmongMultiple] termsType='Z3' 동일 타입 2건 중 REG_TIME이 더 최신인
     * 970022가 선택됨을 검증(ORDER BY REG_TIME DESC LIMIT 1). 오래된 970021은 반환되지 않는다.
     */
    @Test
    void NTC_getNotice_latestAmongMultiple() {
        String termsType = "Z3";
        Map<String, String> p = Map.of(
            "TERMS_TYPE", termsType,
            "SEQ_OLD", "970021", "LINK_OLD", "https://example.com/terms/v1",
            "SEQ_NEW", "970022", "LINK_NEW", "https://example.com/terms/v2-latest");
        executeSqlTemplate(TEARDOWN_SQL, p);
        executeSqlTemplate(SETUP_SQL, p);
        try {
            given().log().ifValidationFails().baseUri(BASE_URL)
                .cookie("SESSION", sessionId)
                .header("X-Requested-With", "XMLHttpRequest")
                .queryParam("termsType", termsType)
            .when()
                .get(API_PATH)
            .then().log().ifValidationFails()
                .statusCode(200)
                .body("err", equalTo("000"))
                .body("mngTermsSeq", equalTo(970022))
                .body("link", equalTo("https://example.com/terms/v2-latest"));
        } finally {
            executeSqlTemplate(TEARDOWN_SQL, p);
        }
    }

    // =====================================================================
    // ATC — 데이터 미존재 / 요청 거부
    // 체크리스트: ATC_param_noData, ATC_code400 (test-plan)
    // =====================================================================

    /**
     * [ATC_getNotice_noMatchingData] 존재하지 않는 termsType='Z9' → 매칭 행 없음.
     * DAO가 null 반환 → 빈 JSON({}). (test-plan ATC_param_noData)
     */
    @Test
    void ATC_getNotice_noMatchingData() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "Z9")
        .when()
            .get(API_PATH)
        .then().log().ifValidationFails()
            .statusCode(200)
            .body("mngTermsSeq", nullValue())
            .body("err", nullValue());
    }

    /**
     * [ATC_getNotice_noSession] 세션 없이 호출 → SuperAdminLoginInterceptor가
     * res.sendRedirect("/web/login") (비-ajax 경로) → 302 리다이렉트로 요청 거부.
     * (test-plan ATC_code400 — 이 읽기 엔드포인트에는 400 분기가 없으므로 인증 거부 경로로 매핑)
     */
    @Test
    void ATC_getNotice_noSession() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .redirects().follow(false)
            .queryParam("termsType", "Z1")
        .when()
            .get(API_PATH)
        .then().log().ifValidationFails()
            .statusCode(302)
            .header("Location", containsString("/web/login"));
    }

    // =====================================================================
    // VTC — RED 파라미터 termsType 표준 rule (NULL/EMPTY 필수 + DB_WHERE: WHITE_SPACE/SPECIAL_CHAR)
    // 모두 매칭 행 없음 → 빈 JSON({}). LENGTH/INVALID_FORMAT rule은 varchar(2) 읽기전용 WHERE라 무의미 → 미적용.
    // =====================================================================

    /** [VTC_termsType_NULL] termsType 파라미터 생략 → WHERE TERMS_TYPE = null → 결과 없음. */
    @Test
    void VTC_termsType_NULL() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when()
            .get(API_PATH)
        .then().log().ifValidationFails()
            .statusCode(200)
            .body("mngTermsSeq", nullValue())
            .body("err", nullValue());
    }

    /** [VTC_termsType_EMPTY] termsType='' → WHERE TERMS_TYPE = '' → 결과 없음. */
    @Test
    void VTC_termsType_EMPTY() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "")
        .when()
            .get(API_PATH)
        .then().log().ifValidationFails()
            .statusCode(200)
            .body("mngTermsSeq", nullValue())
            .body("err", nullValue());
    }

    /** [VTC_termsType_WHITE_SPACE] termsType=' \t\n' → trim 미수행 시에도 매칭 행 없음. */
    @Test
    void VTC_termsType_WHITE_SPACE() {
        given().log().ifValidationFails().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", " \t\n")
        .when()
            .get(API_PATH)
        .then().log().ifValidationFails()
            .statusCode(200)
            .body("mngTermsSeq", nullValue())
            .body("err", nullValue());
    }

